class Solution {
public:
    bool canPartition(const string& s, int idx, int target, int current) {
        if (idx == (int)s.size()) return current == target;
        if (current > target) return false;
        int num = 0;
        for (int i = idx; i < (int)s.size(); i++) {
            num = num * 10 + (s[i] - '0');
            if (canPartition(s, i + 1, target, current + num)) return true;
        }
        return false;
    }

    int punishmentNumber(int n) {
        int sum = 0;
        for (int i = 1; i <= n; i++) {
            int sq = i * i;
            string s = to_string(sq);
            if (canPartition(s, 0, i, 0)) sum += sq;
        }
        return sum;
    }
};
